{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "In healthy subjects, 5-hydroxyrofecoxib had an oral bioavailability of 0.140 after a 25 mg oral dose relative to i.v., a direct human measurement below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Epicillin showed only 3.9% oral bioavailability in patients with cystic fibrosis, a direct low-F measurement.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Galocitabine was reported to have extremely low oral bioavailability in humans, with about 50% of the dose excreted unchanged in urine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "9-Nitrocamptothecin has very low absolute oral bioavailability in patients, with high interpatient and intrapatient variability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "EM574 oral bioavailability in humans is approximately 2%, estimated from oral clearance about 50-fold higher than hepatic blood flow.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Naringin oral bioavailability in humans is only 5-9%, a direct low-F measurement.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Omadacycline, the highest-transfer analogue, has a measured absolute oral bioavailability of 34.5% in healthy adults, which is above the threshold and contradicts a low prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low F (<20%). Multiple high-transfer experimental analogues show low absolute oral bioavailability (2-15%), and the query's very low logD, high TPSA, and 11 H-bond acceptors are consistent with poor passive permeability. The single high-F omadacycline result is outweighed by the convergent low-F evidence and by structural features that make its absorption mechanism less applicable to the neutral, highly polar query.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "The query's permeability, transporter interactions, and metabolic stability are not experimentally characterized.",
    "The omadacycline dataset contains an internal conflict (C20 0.5% vs. majority 34.5%), adding uncertainty to the highest-transfer analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

